<?php
 class RouterTest extends PHPUnit_Framework_TestCase { public function testConstruct() { $router = new \Slim\Router(); $this->assertAttributeEquals(array(), 'routes', $router); } public function testMap() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function() {}); $router->map($route); $this->assertAttributeContains($route, 'routes', $router); } public function testAddNamedRoute() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $router->addNamedRoute('foo', $route); $property = new \ReflectionProperty($router, 'namedRoutes'); $property->setAccessible(true); $rV = $property->getValue($router); $this->assertSame($route, $rV['foo']); } public function testAddNamedRouteWithDuplicateKey() { $this->setExpectedException('RuntimeException'); $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $router->addNamedRoute('foo', $route); $router->addNamedRoute('foo', $route); } public function testGetNamedRoute() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $property = new \ReflectionProperty($router, 'namedRoutes'); $property->setAccessible(true); $property->setValue($router, array('foo' => $route)); $this->assertSame($route, $router->getNamedRoute('foo')); $this->assertNull($router->getNamedRoute('bar')); } public function testGetNamedRoutes() { $router = new \Slim\Router(); $route1 = new \Slim\Route('/foo', function () {}); $route2 = new \Slim\Route('/bar', function () {}); $propertyRouterRoutes = new \ReflectionProperty($router, 'routes'); $propertyRouterRoutes->setAccessible(true); $propertyRouterRoutes->setValue($router, array($route1, $route2)); $propertyRouterNamedRoutes = new \ReflectionProperty($router, 'namedRoutes'); $propertyRouterNamedRoutes->setAccessible(true); $propertyRouterNamedRoutes->setValue($router, null); $propertyRouteName = new \ReflectionProperty($route2, 'name'); $propertyRouteName->setAccessible(true); $propertyRouteName->setValue($route2, 'bar'); $namedRoutes = $router->getNamedRoutes(); $this->assertCount(1, $namedRoutes); $this->assertSame($route2, $namedRoutes['bar']); } public function testHasNamedRoute() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $property = new \ReflectionProperty($router, 'namedRoutes'); $property->setAccessible(true); $property->setValue($router, array('foo' => $route)); $this->assertTrue($router->hasNamedRoute('foo')); $this->assertFalse($router->hasNamedRoute('bar')); } public function testGetCurrentRoute() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $property = new \ReflectionProperty($router, 'currentRoute'); $property->setAccessible(true); $property->setValue($router, $route); $this->assertSame($route, $router->getCurrentRoute()); } public function testGetCurrentRouteIfMatchedRoutes() { $router = new \Slim\Router(); $route = new \Slim\Route('/foo', function () {}); $propertyMatchedRoutes = new \ReflectionProperty($router, 'matchedRoutes'); $propertyMatchedRoutes->setAccessible(true); $propertyMatchedRoutes->setValue($router, array($route)); $propertyCurrentRoute = new \ReflectionProperty($router, 'currentRoute'); $propertyCurrentRoute->setAccessible(true); $propertyCurrentRoute->setValue($router, null); $this->assertSame($route, $router->getCurrentRoute()); } public function testGetCurrentRouteIfNoMatchedRoutes() { $router = new \Slim\Router(); $propertyMatchedRoutes = new \ReflectionProperty($router, 'matchedRoutes'); $propertyMatchedRoutes->setAccessible(true); $propertyMatchedRoutes->setValue($router, array()); $propertyCurrentRoute = new \ReflectionProperty($router, 'currentRoute'); $propertyCurrentRoute->setAccessible(true); $propertyCurrentRoute->setValue($router, null); $this->assertNull($router->getCurrentRoute()); } public function testGetMatchedRoutes() { $router = new \Slim\Router(); $route1 = new \Slim\Route('/foo', function () {}); $route1 = $route1->via('GET'); $route2 = new \Slim\Route('/foo', function () {}); $route2 = $route2->via('POST'); $route3 = new \Slim\Route('/bar', function () {}); $route3 = $route3->via('PUT'); $routes = new \ReflectionProperty($router, 'routes'); $routes->setAccessible(true); $routes->setValue($router, array($route1, $route2, $route3)); $matchedRoutes = $router->getMatchedRoutes('GET', '/foo'); $this->assertSame($route1, $matchedRoutes[0]); } public function testUrlFor() { $router = new \Slim\Router(); $route1 = new \Slim\Route('/hello/:first/:last', function () {}); $route1 = $route1->via('GET')->name('hello'); $route2 = new \Slim\Route('/path/(:foo\.:bar)', function () {}); $route2 = $route2->via('GET')->name('regexRoute'); $routes = new \ReflectionProperty($router, 'namedRoutes'); $routes->setAccessible(true); $routes->setValue($router, array( 'hello' => $route1, 'regexRoute' => $route2 )); $this->assertEquals('/hello/Josh/Lockhart', $router->urlFor('hello', array('first' => 'Josh', 'last' => 'Lockhart'))); $this->assertEquals('/path/Hello.Josh', $router->urlFor('regexRoute', array('foo' => 'Hello', 'bar' => 'Josh'))); } public function testUrlForIfNoSuchRoute() { $this->setExpectedException('RuntimeException'); $router = new \Slim\Router(); $router->urlFor('foo', array('abc' => '123')); } } 